import{_ as t,C as r,o as n,c as i,a5 as l,E as s}from"./chunks/framework.BwlBv862.js";const b=JSON.parse('{"title":"プラグインをインストール・管理する","description":"","frontmatter":{"title":"プラグインをインストール・管理する","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"93c8811682d0baa5bd18b571503fce483cf1f464e94b94bc933241bf277d23d4","translationRevision":"4d30369c30051c054d86732dd0d38ca7ef76fc45fde01ade6b30844a51f6d961","order":10},"headers":[],"relativePath":"ja/user/plugins/index.md","filePath":"ja/user/plugins/index.md","lastUpdated":1794611623000}'),o={name:"ja/user/plugins/index.md"};function d(c,e,u,p,h,f){const a=r("DemoFrame");return n(),i("div",null,[e[0]||(e[0]=l('<h1 id="install-and-manage-plugins" tabindex="-1">プラグインをインストール・管理する <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to &quot;プラグインをインストール・管理する {#install-and-manage-plugins}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>連携を追加し、要求アクセスを確認してアクションが使えることを確かめます。プラグインの OS、アーキテクチャ、ホストバージョンに対応するデスクトップパッケージが必要です。リモートカタログとダウンロードにはネットワークが、一部のアカウント方式サービスには <a href="./../cloud/account.html">Cloud サインイン</a> も必要です。</p><h2 id="review-before-enabling" tabindex="-1">有効化前に確認する <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to &quot;有効化前に確認する {#review-before-enabling}&quot;">​</a></h2><ol><li><strong>プラグイン</strong> のインストール済み、探す、アップデートを確認します。探すはプラグイン項目だけを取得します。自動化テンプレートとプロファイルは <a href="./../automations/templates.html">自動化</a> にあります。</li><li>説明、バージョン、互換性、ランタイムを確認します。見慣れた表示名だけを信じず、発行者と要求機能・権限を確認します。</li><li>インストール画面でパッケージをプレビューし、確定前に正確なバージョン、署名、要求アクセス、既存版からの変更を読みます。</li><li>ジョブ結果を待ちます。ダウンロード、インストール、有効化は別段階で、カタログカードだけでは実行準備は完了していません。</li><li>プラグインの設定または接続を開き、専用欄だけにアドレスと認証情報を入力します。提供されていれば宣言済みの接続確認を使います。</li><li>有効化後、アクション種別やページの表示を確認します。強力な外部アクションを結び付ける前に、範囲を絞った<a href="./../automations/first-rule.html">ログ記録ルール</a> を作ります。</li></ol><p>プラグインはネイティブコードや別プロセスを実行できます。プロセス分離はクラッシュを切り離せても OS のサンドボックスではありません。信頼できる発行者のソフトウェアを使います。有効な署名は確認された出所を示しますが、すべての処理が用途に適するとは限りません。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>パッケージ確認、インストールジョブ、設定、バージョン管理を利用できます。実際のアクションはマニフェスト、ホスト機能、外部サービスに依存します。イベントプロセッサーには専用パネルがあり、イベントに任意の分析フィールドを追加できます。生のフィールドとは区別されます。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>失敗時はジョブのエラーから互換性、署名、ランタイム、取得の問題を読みます。エラーを消すために検証を弱めないでください。更新後の問題では保持版を確認し、可能ならロールバックします。無効化・削除前に依存する自動化を確認し、プラグインのデータと設定を<a href="./../preferences/backups.html">バックアップ</a> します。</p>',10)),s(a,{scenario:"plugins",locale:"ja",tour:"plugin",title:"デモ: プラグイン"})])}const _=t(o,[["render",d]]);export{b as __pageData,_ as default};
